using Swashbuckle.AspNetCore.Annotations;namespace GraphApi.Models.ARC.Archivos{    [SwaggerSchema("Modelo de lectura de un Archivo")]    [GraphQLDescription("Objeto que representa un Archivo existente.")]    public class clReadArchivos    {        [SwaggerSchema("Identificador único del Archivo")]        [GraphQLDescription("Identificador único del Archivo")]        public int? ArchivoID { get; set; }        [SwaggerSchema("Nombre")]        [GraphQLDescription("Nombre")]        public string? Nombre { get; set; } = default!;        [SwaggerSchema("Ruta")]        [GraphQLDescription("Ruta")]        public string? Ruta { get; set; } = default!;        [SwaggerSchema("TipoArchivoID")]        [GraphQLDescription("TipoArchivoID")]        public int? TipoArchivoID { get; set; }        [SwaggerSchema("TipoArchivo")]        [GraphQLDescription("TipoArchivo")]        public string? TipoArchivo { get; set; } = default!;        [SwaggerSchema("EsPrivado")]        [GraphQLDescription("EsPrivado")]        public bool? EsPrivado { get; set; }        [SwaggerSchema("bEliminado")]        [GraphQLDescription("bEliminado")]        public bool? bEliminado { get; set; }    }    [SwaggerSchema("Modelo de creación de un Archivo")]    [GraphQLDescription("Input para crear un Archivo.")]    public class clCreateArchivos    {        [GraphQLNonNullType] [SwaggerSchema("Nombre")]        [GraphQLDescription("Nombre")]        public string Nombre { get; set; } = default!;        [GraphQLNonNullType] [SwaggerSchema("Ruta")]        [GraphQLDescription("Ruta")]        public string Ruta { get; set; } = default!;        [SwaggerSchema("TipoArchivoID")]        [GraphQLDescription("TipoArchivoID")]        public int? TipoArchivoID { get; set; }        [GraphQLNonNullType] [SwaggerSchema("EsPrivado")]        [GraphQLDescription("EsPrivado")]        public bool EsPrivado { get; set; }        [GraphQLNonNullType] [SwaggerSchema("bEliminado")]        [GraphQLDescription("bEliminado")]        public bool bEliminado { get; set; }    }    [SwaggerSchema("Modelo de actualización de un Archivo")]    [GraphQLDescription("Input para actualizar parcialmente un Archivo.")]    public class clUpdateArchivos    {        [SwaggerSchema("Identificador único del Archivo")]        [GraphQLDescription("Identificador único del Archivo")]        public int? ArchivoID { get; set; }        [SwaggerSchema("Nombre")]        [GraphQLDescription("Nombre")]        public string? Nombre { get; set; }        [SwaggerSchema("Ruta")]        [GraphQLDescription("Ruta")]        public string? Ruta { get; set; }        [SwaggerSchema("TipoArchivoID")]        [GraphQLDescription("TipoArchivoID")]        public int? TipoArchivoID { get; set; }        [SwaggerSchema("EsPrivado")]        [GraphQLDescription("EsPrivado")]        public bool? EsPrivado { get; set; }        [SwaggerSchema("bEliminado")]        [GraphQLDescription("bEliminado")]        public bool? bEliminado { get; set; }    }}